# function_app.py  (Python v2 model)
import json, logging
import azure.functions as func

app = func.FunctionApp(http_auth_level=func.AuthLevel.FUNCTION)

# Trigger: POST /api/orders. Output binding: put the order on the "orders" queue.
@app.route(route="orders", methods=["POST"])
@app.queue_output(arg_name="msg", queue_name="orders", connection="Storage")
def create_order(req: func.HttpRequest, msg: func.Out[str]) -> func.HttpResponse:
    order = req.get_json()
    msg.set(json.dumps(order))           # sends the queue message
    return func.HttpResponse(status_code=202)

# Trigger: a new message on the "orders" queue
@app.queue_trigger(arg_name="m", queue_name="orders", connection="Storage")
def process_order(m: func.QueueMessage) -> None:
    logging.info("processing %s", m.get_json()["id"])

@app.timer_trigger(arg_name="t", schedule="0 0 2 * * *")   # 02:00 UTC daily
def nightly(t: func.TimerRequest) -> None:
    logging.info("nightly cleanup")

