resource profile 'Microsoft.Cdn/profiles@2024-09-01' = {
  name: 'afd-orders', location: 'global', sku: { name: 'Premium_AzureFrontDoor' }
}
resource endpoint 'Microsoft.Cdn/profiles/afdEndpoints@2024-09-01' = { parent: profile, name: 'orders', location: 'global' }
resource web 'Microsoft.Cdn/profiles/originGroups@2024-09-01' = {
  parent: profile, name: 'web'
  properties: {
    loadBalancingSettings: { sampleSize: 4, successfulSamplesRequired: 3, additionalLatencyInMilliseconds: 50 }
    healthProbeSettings: { probePath: '/healthz', probeProtocol: 'Https', probeRequestType: 'GET', probeIntervalInSeconds: 30 }
  }
}
// priority 1 = primary (West Europe), priority 2 = failover (North Europe)
resource origins 'Microsoft.Cdn/profiles/originGroups/origins@2024-09-01' = [for (app, i) in ['orders-weu', 'orders-neu']: {
  parent: web, name: app
  properties: { hostName: '${app}.azurewebsites.net', originHostHeader: '${app}.azurewebsites.net', priority: i + 1, weight: 1000 }
}]
resource route 'Microsoft.Cdn/profiles/afdEndpoints/routes@2024-09-01' = {
  parent: endpoint, name: 'default', dependsOn: [origins]
  properties: {
    originGroup: { id: web.id }, patternsToMatch: ['/*'], supportedProtocols: ['Http', 'Https']
    httpsRedirect: 'Enabled', forwardingProtocol: 'HttpsOnly', linkToDefaultDomain: 'Enabled'
  }
}

{
  "properties": {
    "displayName": "Require a costCenter tag on resource groups",
    "mode": "All",
    "parameters": {
      "effect": { "type": "String", "allowedValues": ["Audit", "Deny"], "defaultValue": "Audit" }
    },
    "policyRule": {
      "if": {
        "allOf": [
          { "field": "type", "equals": "Microsoft.Resources/subscriptions/resourceGroups" },
          { "field": "tags['costCenter']", "exists": "false" }
        ]
      },
      "then": { "effect": "[parameters('effect')]" }
    }
  }
}
